"""Tenant-scoped marketing experiments; decisions never change external campaigns automatically."""
from datetime import datetime
from core.database import Base
from sqlalchemy import Column,DateTime,Integer,String,Text,UniqueConstraint
class FactoryMarketingExperiment(Base):
 __tablename__="factory_marketing_experiments";__table_args__=(UniqueConstraint("project_id","experiment_key",name="uq_factory_marketing_experiment_key"),{"extend_existing":True})
 id=Column(String(100),primary_key=True);project_id=Column(Integer,nullable=False,index=True);agent_path=Column(String(500),nullable=False,index=True);tenant_id=Column(String(100),nullable=False,index=True);client_id=Column(String(100),nullable=False,index=True);plan_id=Column(String(100),nullable=False,index=True);experiment_number=Column(String(100),nullable=False,unique=True,index=True);experiment_key=Column(String(120),nullable=False,index=True);hypothesis=Column(Text,nullable=False);evidence_reference=Column(String(255),nullable=False);status=Column(String(32),nullable=False,default="draft",server_default="draft",index=True);created_by=Column(String(255),nullable=False,index=True);reviewed_by=Column(String(255),index=True);review_reference=Column(String(255));revision=Column(Integer,nullable=False,default=1,server_default="1");created_at=Column(DateTime(timezone=True),default=datetime.now);updated_at=Column(DateTime(timezone=True),default=datetime.now,onupdate=datetime.now)
class FactoryExperimentDecision(Base):
 __tablename__="factory_experiment_decisions";__table_args__=(UniqueConstraint("experiment_id","destination",name="uq_factory_experiment_decision_destination"),{"extend_existing":True})
 id=Column(String(100),primary_key=True);project_id=Column(Integer,nullable=False,index=True);agent_path=Column(String(500),nullable=False,index=True);tenant_id=Column(String(100),nullable=False,index=True);client_id=Column(String(100),nullable=False,index=True);plan_id=Column(String(100),nullable=False,index=True);decision_number=Column(String(100),nullable=False,unique=True,index=True);experiment_id=Column(String(100),nullable=False,index=True);experiment_number=Column(String(100),nullable=False);destination=Column(String(32),nullable=False);manifest_json=Column(Text,nullable=False);manifest_fingerprint=Column(String(64),nullable=False);status=Column(String(32),nullable=False,default="pending",server_default="pending",index=True);decided_by=Column(String(255),nullable=False,index=True);acknowledged_by=Column(String(255),index=True);acknowledgement_reference=Column(String(255));revision=Column(Integer,nullable=False,default=1,server_default="1");created_at=Column(DateTime(timezone=True),default=datetime.now);acknowledged_at=Column(DateTime(timezone=True))
